namespace KlikerBlocks;

internal static class AppHelp
{
    public static string Introduction => IntroductionTemplate.Replace("{{VERSION}}", AppIdentity.VersionLabel);

    private const string IntroductionTemplate = """
        Kliker Blocks — справка по визуальным сценариям Windows

        Версия {{VERSION}}, публичная бета. При первом запуске выберите русский или английский до открытия редактора; демонстрация последует этому выбору. Позже язык меняется в меню «Языки». Создавайте граф из блоков, настраивайте переменные, условия, циклы, действия с мышью и клавиатурой, файлами, окнами, звуком и экраном. Сценарий запускается из редактора, компактной панели или трея.

        В редакторе доступны два представления одного проекта: визуальные блоки и текстовый код Kliker Blocks. Для запуска файла используйте блок «Запустить файл»: выберите установленную программу из списка, откройте файл через Проводник либо укажите путь вручную.

        Демонстрация «Что я умею» создаёт собственный документ Блокнота, проверяет активную вкладку перед вводом, рисует в Paint и ищет выбранный цвет. Она не требует машинного перевода. Для блоков перевода нужен отдельно запущенный сервис или добровольно установленная офлайн-модель выбранной языковой пары.

        Выпуск содержит отдельные установщики и переносимые сборки для x64 и x86. Для 64-разрядной Windows выбирайте x64; для 32-разрядной — x86. Установщик предлагает папку, значок на рабочем столе, запуск после установки и автозапуск. Меню «Сценарий → Запускать вместе с Windows» включает или выключает автозапуск для текущей учётной записи. Чтобы закрепить программу на панели задач, используйте меню Windows у значка запущенной программы.

        Имена переменных и массивов содержат только A–Z, a–z, 0–9 и _. Первый символ — буква или _. Например: user_name, count_2. Подробности, ограничения и примеры каждого блока ищите в разделах справки слева.

        Перед управлением чужими окнами сохраните свою работу. Действия с рабочим столом требуют согласия пользователя; открытые окна и созданные файлы могут остаться после остановки сценария.
        """;

    public static string For(string kind) => kind switch
    {
        "ShowcaseStep" => "Внутренний шаг графа «Что я умею»: открывает отдельные окна Блокнота и Paint, печатает и проверяет текст, задаёт интерактивный вопрос, рисует и ищет цвет. Перевод и установка модели в демонстрацию не входят. Параметр Action задаёт шаг, Caption — подпись. Служебный шаг работает в контексте встроенной демонстрации, а не отдельного обычного сценария. Остановка прерывает ожидание и дальнейшие действия, но открытые окна остаются; буфер обмена после копирования изменён.",
        "Start" => "Точка входа. В проекте нужен ровно один блок «Старт». Его выход «Далее» ведёт к первому действию.",
        "Description" => "Фоновая область с названием над группой блоков. Не участвует в выполнении сценария и не имеет входов/выходов. Перетащите её за верхнюю полосу или край; тяните нижний правый угол для изменения размера. В свойствах можно задать название, размеры, цвет #RRGGBB и непрозрачность 0–100 %. Щелчок внутри не выбирает область; Shift-рамка выберет её лишь при полном охвате. Внутренние блоки не привязаны к области и двигаются отдельно.",
        "WatchCursor" => "Возвращает системный курсор при смещении. Активация: сразу, переключатель или удержание клавиши; дополнительно можно требовать ЛКМ/ПКМ/СКМ. Клавишу можно назначить нажатием в окне захвата. Плавающий индикатор: красный — ожидание, зелёный — переключатель включён. Пример: F9 + ЛКМ. Длительность 0 в однопроходном режиме — до остановки, а в циклическом — одна проверка за проход.",
        "MoveCursor" => "Разово перемещает системный курсор через SetCursorPos. Режимы: центр текущего монитора; абсолютные X/Y; смещение относительно текущей точки; смещение относительно центра монитора. Значения OffsetX/OffsetY могут быть отрицательными. Для программ, читающих относительное движение, используйте отдельный блок «Сдвиг мыши».",
        "MoveRelative" => "Посылает относительный сдвиг через стандартный Windows SendInput: положительный X — вправо, положительный Y — вниз. «Задержка» откладывает начало. При времени 0 или одном шаге весь сдвиг отправляется сразу; время больше 0 и несколько шагов распределяют точный суммарный ΔX/ΔY по времени. Для разового запуска по клавише выберите у блока «Если клавиша нажата» режим «При новом нажатии». Для повторения при удержании выберите «Пока удерживается» и «Повторять до остановки». Обратный сдвиг создаётся вторым блоком с отрицательными ΔX/ΔY после «Паузы». Это не абсолютная экранная точка и не измерение положения камеры или игрового прицела. Остановка — Ctrl+Alt+F7; макросы используйте только там, где они разрешены.",
        "InputGroup" => "Неделимая группа действий для общей очереди мыши, клавиатуры, буфера обмена и активного окна. Соедините «Тело» с первым действием и завершите блоком «Конец ветки»; после этого выполняется «Далее». Например: клик по полю → ввод текста. Право ввода освобождается автоматически при завершении, остановке, ошибке и превышении указанного времени (100–60000 мс). Не помещайте сюда длительное ожидание. «Параллельно» внутри группы запрещено. Отдельные действия и без группы автоматически занимают очередь только на время своего выполнения.",
        "Click" => "Нажимает и отпускает левую, правую или среднюю кнопку в текущей точке. Количество ограничено 1–100. Для удержания и перетаскивания используйте «Кнопка мыши: Нажать», «Переместить курсор», «Кнопка мыши: Отпустить».",
        "MouseButton" => "Отдельное нажатие или отпускание кнопки. Удержанные блоком кнопки автоматически отпускаются при завершении или остановке сценария.",
        "Wheel" => "Прокручивает колесо мыши вверх или вниз на 1–100 шагов.",
        "Key" => "Короткое нажатие клавиши. Допускаются A–Z, 0–9, F1–F24, ENTER, SPACE, TAB, ESC, CTRL, ALT, SHIFT, BACKSPACE, стрелки, HOME, END, DELETE, INSERT, PAGEUP, PAGEDOWN, WIN.",
        "KeyState" => "Нажимает или отпускает клавишу без автоматического отпускания между блоками. Подходит для сочетаний, например CTRL вниз → A → CTRL вверх. При остановке Kliker Blocks отпустит удержанные им клавиши. Соответствует KEYDOWN/KEYUP.",
        "VirtualKey" => "Нажимает или отпускает клавишу по десятичному коду Windows VK (1–255). Примеры: 13=Enter, 17=Ctrl, 18=Alt, 27=Esc, 32=Пробел, 46=Delete, 65=A, 90=Z, 112=F1, 118=F7. Введите код: под полем появится его название. Нажмите «Таблица кодов клавиш VK…» для полного справочника с поиском. Клавиши OEM зависят от раскладки; ввод паролей также может попасть в макрос.",
        "TypeText" => "Посылает Unicode-символы в активное окно через Windows SendInput. Поддерживает кириллицу; не требует менять раскладку. Целевое приложение должно принимать обычный системный ввод.",
        "ClipboardSet" => "Помещает заданный текст в буфер обмена Windows. Не вставляет его автоматически: для вставки добавьте блоки CTRL вниз → V → CTRL вверх.",
        "ClipboardGet" => "Читает текст из буфера обмена Windows в указанную переменную. Если буфер не содержит текста, переменная получает пустую строку. Для чтения содержимого приложения сначала используйте его команду копирования.",
        "TextFile" => "Работает с UTF-8 текстовым файлом: прочитать строку, узнать число строк, заменить строку («Записать»), вставить со сдвигом прежних строк, добавить в конец, добавить или полностью перезаписать файл одной строкой, удалить строку, очистить либо удалить файл. Нумерация строк начинается с 1; вставка за концом файла добавляет строку в конец. Результат чтения или новое количество строк записывается в переменную. Путь относителен папке проекта. Файлы более 8 МиБ не обрабатываются при чтении и редактировании; удаление файла доступно и без чтения содержимого.",
        "TextFileArray" => "Читает UTF-8 текстовый файл в массив (TFREADARR) либо записывает массив по одной строке на элемент (TFWRITEARR). Индексы начинаются с 0; при чтении прежний массив заменяется. Для разреженного массива отсутствующие элементы записываются как 0. Число строк — в переменной результата. Не более 10000 строк и 8 МиБ; элементы с переводом строки нельзя записать.",
        "CsvTable" => "Работает с CSV-таблицей UTF-8 без Excel: читает или записывает ячейку по номерам строки и столбца от 1, считает строки либо сохраняет в отдельный файл строки, где выбранная ячейка содержит текст фильтра. Разделитель: запятая, точка с запятой или TAB; кавычки и переносы внутри ячейки поддерживаются. Запись заменяет файл атомарно, но перед изменением важных таблиц сохраните копию. Не более 8 МиБ, 10000 строк и 256 столбцов. Результат пишется в переменную; пути относительны папке проекта. Пример: создайте data.csv с двумя строками, прочитайте строку 1, столбец 2 и выведите переменную csv_result в журнал.",
        "ExcelTable" => "Работает с файлами .xlsx: читает или записывает ячейку, возвращает номер последней заполненной строки и ищет номера строк, где ячейка содержит заданный текст. Номера строк и столбцов начинаются с 1. Пустое имя листа выбирает первый лист; при записи можно создать новый файл или лист. Запись сохраняется через временный файл с заменой исходного. Ограничение входного файла — 32 МиБ, поиск — первые 10000 строк. Результат записывается в переменную. Пример: создайте workbook.xlsx, запишите в A1 слово Hello, затем прочитайте A1 и выведите ${excel_result} в журнал. Макросы и формат .xls не поддерживаются.",
        "PdfText" => "Извлекает текст из PDF: одну страницу, весь документ или количество страниц. Номер страницы начинается с 1; для всего документа допускается не более 100 страниц. Размер файла — до 32 МиБ, результат — до 100000 символов. Полученный текст записывается в переменную. Скан без текстового слоя не содержит извлекаемого текста: для него используйте OCR. Пример: укажите document.pdf, выберите «Количество страниц», затем выведите ${pdf_result} в журнал. Парольные PDF могут требовать предварительного открытия в другой программе.",
        "FileQueue" => "Очередь обрабатывает файлы из папки по маске в порядке имени. «Взять следующий» записывает полный путь в переменную и ведёт по выходу «Есть файл» либо «Очередь пуста». Затем обработайте файл и отдельным блоком очереди отметьте его готовым или ошибкой; в поле «Текущий файл» укажите ${queue_file}. Состояние хранится в видимом JSON-файле, не удаляет исходные файлы. Незавершённый файл возвращается в очередь после 15 минут. Максимум 10000 файлов. Пример: взять следующий *.txt → прочитать файл → отметить готовым → вернуться к блоку взятия следующего. Для ошибок подключите отдельную ветку.",
        "Checkpoint" => "Сохраняет следующий блок, скалярные переменные и массивы в видимом JSON-файле. Для продолжения откройте тот же граф и выберите «Сценарий → Продолжить с контрольной точки…». Если граф с момента сохранения изменился, контрольная точка отклоняется; исходный файл не удаляется. Файл ограничен 4 МиБ. Контрольная точка не восстанавливает открытые окна, нажатые клавиши и другие внешние состояния. Пример: Старт → задать переменную counter=1 → контрольная точка → сообщение ${counter}. После сохранения остановите сценарий и продолжите из меню.",
        "IniFile" => "Читает или записывает значение ключа в секции INI-файла. Если секции/ключа при чтении нет, возвращает пустую строку. При записи отсутствующие секция/ключ создаются. Результат помещается в переменную.",
        "DirectoryList" => "Перечисляет файлы либо папки каталога по маске (например *.txt). Можно задать каталог и маску отдельно или заполнить «Путь с маской», как в GETFILELIST/GETDIRLIST. В последнем случае маска должна содержать * или ?. В массив попадают имена без каталога с индекса 0; число элементов пишется в переменную. Старое содержимое массива удаляется. Не более 10000 записей, без вложенных папок.",
        "HttpGet" => "Выполняет GET по HTTP/HTTPS и сохраняет ответ UTF-8 в переменную. Необязательные заголовки пишите как «Имя: значение», каждый с новой строки (до 32, всего не более 8192 символов). Поля поддерживают ${переменная}. Таймаут 100–60000 мс, ответ до 8 МиБ. HTTP-ошибки завершают сценарий. Используйте только доверенные адреса: URL и заголовки могут содержать чувствительные данные.",
        "HttpPost" => "Отправляет тело UTF-8 запросом POST на указанный HTTP/HTTPS адрес. Выберите JSON, обычный текст или данные формы. Тело ограничено 1 МиБ, ответ — 8 МиБ, таймаут 100–60000 мс. Ответ и числовой код HTTP записываются в две переменные; код 4xx/5xx доступен для проверки в следующем блоке. Текст и заголовки передаются выбранному серверу, поэтому указывайте только доверенный адрес. Пример: задайте собственный тестовый URL и тело {\"name\":\"Alex\"; затем выведите ${http_status} в журнал.",
        "JsonValue" => "Берёт JSON-строку или ${переменную} и извлекает поле по пути вроде user.name или items[0].id. Результат сохраняется в переменную. Строка возвращается без кавычек, другие значения — в JSON-представлении. Ошибка разбора или отсутствующее поле останавливают сценарий. Пример: JSON {\"user\":{\"name\":\"Alex\"}}, путь user.name → Alex.",
        "TranslateText" => "Новый блок по умолчанию использует LibreTranslate: укажите адрес работающего сервиса /translate. Адрес 127.0.0.1:5000 без запущенного сервера даст ошибку подключения. Для офлайн-режима нажмите «Скачать офлайн-пару языков…»: после подтверждения Kliker Blocks загрузит Python, Argos и нужные модели, а блок переключится на «Argos локально». Укажите коды ru, en, fr, zh, es или de; для Argos нужен конкретный исходный язык, не auto. Текст поддерживает ${variable} или =выражение; ответ записывается в Result. До 16000 символов, таймаут 100–60000 мс. Сетевому сервису текст передаётся наружу; используйте доверенный адрес.",
        "DetectLanguage" => "Определяет язык фразы через /detect сервиса LibreTranslate. Пишет код языка и показатель уверенности в две переменные. Требуется запущенный сервис; локальный Python/Argos сам по себе эту операцию не предоставляет. Если сервис недоступен, сценарий сообщит ошибку.",
        "LanguagePair" => "Проверяет доступность направления перевода. При выборе LibreTranslate запрашивает /languages работающего сервиса, при выборе «Argos локально» проверяет установленные модели и возможный путь через промежуточный язык. Выход — «Да» или «Нет». Для офлайн-проверки сначала установите нужную пару кнопкой в свойствах блока; при ошибке движка или сервиса сценарий останавливается.",
        "TranslateArray" => "Берёт до 500 строк из массива и последовательно переводит их. По умолчанию нужен работающий сервис LibreTranslate. Для офлайн-перевода установите выбранную пару кнопкой в свойствах блока и выберите «Argos локально»; источник должен быть конкретным кодом языка. Результат заменяет указанный массив, количество строк пишется в переменную. При ошибке исходный массив не меняется; остановка прерывает обработку. При включённой галочке журнал показывает размер результата и первые три строки.",
        "Wait" => "Пауза в миллисекундах (0–3 600 000). Остановка прерывает ожидание. Выполняется только когда поток сценария доходит до этого блока. Чтобы задержать возврат курсора, соедините «Если курсор смещён: Да» → «Пауза» → «Переместить курсор». Пауза от выхода «Повторить: Далее» сработает лишь после всех повторов.",
        "WaitEvent" => "Ждёт появления или закрытия окна по части заголовка либо изменения файла. Если состояние окна уже совпадает с условием, блок сразу идёт через «Событие». Изменение файла отслеживается средствами Windows после входа в блок; предыдущие изменения не учитываются. Таймаут 100–3600000 мс ведёт через выход «Таймаут», остановка сценария прерывает ожидание. Пример: окно «Блокнот» появилось → записать сообщение в журнал.",
        "UiWait" => "Ищет элемент Windows через UI Automation по AutomationId, имени и/или типу. Заголовок окна ограничивает поиск; пустой заголовок означает активное окно. Кнопка захвата заполнит селектор по элементу под указателем через три секунды. Выходы: «Найден» и «Таймаут». Пользовательские и игровые интерфейсы могут не предоставлять элементы UI Automation; тогда используйте поиск изображения или координаты. Пример: дождаться кнопки с AutomationId, затем соединить «Найден» с действием.",
        "UiAction" => "Находит элемент по тому же селектору и выполняет действие: нажать, ввести текст, переключить, выбрать или прочитать текст. Результат и текст ошибки записываются в переменные; при ошибке доступен выход «Ошибка». Ввод текста требует поддержки ValuePattern, нажатие — InvokePattern, поэтому не каждый элемент поддерживает каждое действие. Кнопка захвата заполняет селектор под указателем. Пример: захватите кнопку в тестовом окне, соедините «Дождаться элемента: Найден» с этим блоком и проверьте выход в журнале.",
        "SetVariable" => "Создаёт или заменяет переменную. Имя: только A–Z, a–z, 0–9, _; начинается с буквы или _. Например counter_1. Значение — текст, число, ${other_value} или =выражение. Регистр имён не важен; значение действует до завершения текущего запуска.",
        "DefineVariable" => "Объявляет переменную с начальным значением, только если её ещё нет. Существующее значение не меняется. Удобно для счётчика цикла, который должен сохраняться между проходами сценария.",
        "UndefineVariable" => "Удаляет переменную и одноимённый массив (UNDEFINE). После удаления обращение к этому имени как к переменной даёт 0; DEFINE может создать его снова. Системные переменные $_... вычисляются отдельно и удалением не отключаются.",
        "SetVariableByName" => "SETVAR: меняет уже существующую скалярную переменную по имени, переданному строкой. Например, поле имени «$counter» или ${reference}, где reference содержит «$counter». Значение поддерживает =выражение. Несуществующая переменная вызывает ошибку; для создания используйте «Задать переменную» или DEFINE. Читать таким же способом можно выражением =getvar($reference).",
        "MathVariable" => "Изменяет числовую переменную: сложить, вычесть, умножить или разделить на число. Если переменная ещё не создана, арифметика начинает с 0. Операнд может быть ${other_variable}. Дробная часть поддерживается; деление на ноль и нечисловое значение дают понятную ошибку.",
        "ArraySet" => "Записывает значение в массив по индексу 0–1000000. Имя массива — буквы, цифры и _, начиная с буквы или _. В поле индекса и значения можно использовать выражение, начиная с =. Чтение: =$данные[0] или =$данные[$i]. Пустой элемент читается как 0.",
        "ArrayAction" => "Операции: добавить в конец, извлечь последний элемент, записать размер, сортировать как текст, как числа или автоматически. Автосортировка использует числовой порядок, только если все элементы числовые. Для пустого массива извлечение возвращает 0. В выражениях доступны arrsize($массив) и arrpop($массив). Размер разреженного массива равен максимальному индексу плюс один. Массивы живут до конца запуска.",
        "StringSplit" => "Разбивает строку по точному разделителю (STRSEPARATE) и заменяет содержимое выбранного массива. Индексы начинаются с 0; пустые части сохраняются. Количество частей записывается в переменную. Разделитель не должен быть пустым; не более 10000 частей. Поля строки и разделителя поддерживают ${переменная} или =выражение.",
        "IfVariable" => "Проверяет уже заданную переменную. Равно/не равно и «содержит» сравнивают текст без учёта регистра; больше/меньше сравнивают числа. В поле сравнения можно использовать ${имя}. Ветви: «Да» и «Нет».",
        "IfExpression" => "Выполняет выражение из поля (начните с =). Значение 0 или FALSE ведёт по ветке «Нет»; 1 или TRUE — по «Да». Например =if $counter<10. Доступны $переменная, $массив[индекс], + - * / % ** ^, скобки, сравнения, &&/and, ||/or, xor, !/not, rnd, sqrt, strlen и другие функции. Синтаксис if/then/else_if/else описан в разделе «Условные выражения и присваивание».",
        "WhileExpression" => "Повторяет ветку «Тело», пока выражение в поле (начинается с =) даёт ненулевое значение. После каждого тела условие вычисляется заново. Завершите тело «Концом ветки»; после ложного результата выполнится «Далее». Максимум проходов защищает от случайного вечного цикла, значение 0 снимает лимит. Остановка сценария прерывает цикл.",
        "SwitchValue" => "Сравнивает проверяемое значение с пятью вариантами по порядку и запускает только первый совпавший выход. Пустые варианты пропускаются, при отсутствии совпадения используется «Иначе». В полях можно писать =выражение; числа сравниваются численно, остальной текст — без учёта регистра. Для большего числа вариантов соедините выход «Иначе» со следующим блоком «Выбор».",
        "IfMoved" => "Однократно проверяет расстояние курсора от опоры. Выход «Да», если курсор вне порога; иначе «Нет». Для задержки перед возвратом соедините «Да» → «Пауза» → «Переместить курсор». Для непрерывного наблюдения используйте «Следить за курсором».",
        "IfPixel" => "Снимает один пиксель в экранных координатах и сравнивает с заданным цветом. Допуск применяется отдельно к каналам R/G/B (0 — строго). Выход «Да» при совпадении. Фактический цвет записывается в журнал.",
        "WaitPixel" => "Повторно проверяет цвет одного пикселя до совпадения либо таймаута. Интервал задаётся в миллисекундах. Таймаут 0 означает ожидание до остановки. Выходы «Найден» и «Таймаут».",
        "IfKeyDown" => "Проверяет указанную клавишу или кнопку мыши. «Пока удерживается» даёт «Да» на каждом проходе при удержании; «При новом нажатии» — один раз на каждое отдельное нажатие; «Переключатель» меняет сохранённое состояние каждым новым нажатием. В циклическом сценарии проверяется на каждом проходе. Кнопка назначения захватывает клавишу или ЛКМ/ПКМ/СКМ; вручную допустимы LMB/RMB/MMB, ЛКМ/ПКМ/СКМ или код Windows VK.",
        "FindColor" => "Ищет первый пиксель заданного цвета в прямоугольной области. Выходы «Найден» и «Нет». Координаты найденной точки записываются в журнал и доступны следующему блоку «К найденной точке» в этой ветке. Аналог IF_PIXEL_IN.",
        "FindImage" => "Ищет точное изображение BMP/PNG на экране в заданной области. Допуск 0–255 применяется к каждому каналу цвета. Полностью прозрачные пиксели PNG игнорируются. Возвращает верхний левый угол совпадения. Большой шаблон или область могут замедлить работу; защищённый видеовывод может быть недоступен для снимка. Аналог IF_PICTURE_IN.",
        "Screenshot" => "Сохраняет прямоугольную область экрана в PNG. Папка файла создаётся автоматически. Область должна целиком находиться в пределах виртуального рабочего стола.",
        "OcrImage" => "Читает текст из PNG, JPEG, BMP, TIFF, GIF, WebP или PDF локальными средствами и записывает его в переменную. PDF целиком отрисовывается по страницам в оттенках серого (200 DPI), затем распознаётся Tesseract. Поле «Страница PDF»: 1–100 — отдельная страница; 0 — все страницы, максимум 20. GIF и WebP поддерживаются, если установленная сборка Tesseract включает соответствующие декодеры Leptonica. Если движок или язык отсутствует, при первом запуске предлагается скачать 64-разрядную Windows-сборку Tesseract 5.5.3 от UB Mannheim из релиза Tesseract на GitHub (около 24,1 МиБ / 25,3 МБ) и только модели из поля языка; без явного согласия сеть не используется. После согласия установщик запускается через Windows UAC: подтвердите запрос прав, чтобы Tesseract установился в LocalAppData\\KLIKER Blocks\\Tesseract-OCR. После проверки сценарий продолжается без перезапуска. Если запрос UAC отклонён или прав нет, Tesseract не устанавливается; можно указать путь к уже установленному tesseract.exe. Пути к движку и файлу с кириллицей передаются через короткие имена Windows, если система их предоставляет. Файл не отправляется в сеть. На 32-разрядной Windows автоматическая установка недоступна. Ограничения: PDF и изображение до 32 МиБ, изображение страницы до 32 МиБ, общий таймаут 1–120 секунд, результат до 100000 символов. Зашифрованный PDF без пароля распознать нельзя. Пример: укажите scan.pdf и 0, чтобы распознать все страницы; результат попадёт в ocr_text, между страницами ставится разрыв страницы. На мелком или размытом тексте возможны ошибки.",
        "WaitScreenText" => "Периодически делает снимок всего экрана или заданной области и распознаёт её локально через Tesseract, пока не появится искомая строка либо не истечёт таймаут. Искомый текст и результат поддерживают переменные. Выход «Найдено» ведёт к действию при совпадении, «Таймаут» — к обработке отсутствия текста. Таймаут задаётся от 1000 до 600000 мс; распознавание отдельного снимка ограничено остатком этого времени (не более 30 секунд). Tesseract и модель для языка должны быть установлены; для установки используется тот же запрос явного согласия, что и в блоке «Распознать текст». Область задаётся координатами виртуального экрана. Частые снимки увеличивают нагрузку, поэтому настройте разумный интервал. Пример: задайте текст «Готово», интервал 500 мс и соедините «Найдено» с сообщением.",
        "ExtractText" => "Извлекает фрагмент из текста регулярным выражением .NET. Введите выражение захвата, например Invoice\\s+#(\\d+), и номер группы: 0 возвращает всё совпадение, 1 — первую группу. Источник может содержать ${text}; результат записывается в выбранную переменную. При отсутствии совпадения результат будет пустым. Для защиты от слишком сложных выражений применяется таймаут 2 секунды. Пример: для текста Invoice #582 укажите шаблон Invoice\\s+#(\\d+) и группу 1.",
        "BufferCapture" => "Создаёт запомненный снимок экрана для последующих блоков анализа. Выберите весь виртуальный рабочий стол либо прямоугольную область. Координаты границ: левая/верхняя включены, правая/нижняя не включены. Новый снимок заменяет прежний; без повторного вызова проверки читают те же пиксели.",
        "BufferPixel" => "Читает цвет одного пикселя из запомненного снимка в переменную. Координаты экранные. COLORREF — десятичное число вида R + G×256 + B×65536; можно выбрать формат #RRGGBB. Перед блоком выполните «Запомнить экран».",
        "BufferCount" => "Подсчитывает число пикселей выбранного цвета в области запомненного снимка. Допуск 0–255 применяется отдельно к RGB-каналам. Результат — переменная. Аналог PXLCOUNT; для свежего экрана снова вызовите «Запомнить экран».",
        "BufferHash" => "Вычисляет XOR или CRC32 по RGB-пикселям указанной области запомненного снимка и записывает беззнаковое число в переменную. Это удобно для сравнения одной и той же области между двумя вызовами «Запомнить экран». CRC32 использует байты R,G,B в порядке просмотра слева направо, сверху вниз.",
        "BufferReplace" => "Заменяет цвет внутри запомненного снимка, не меняя настоящий экран. Старый цвет -1 означает любой. Число изменённых пикселей записывается в переменную. Для просмотра результата примените «Сохранить снимок». Аналог PXLREPLACE.",
        "BufferFindColor" => "Ищет первый пиксель заданного цвета в запомненном снимке. Ветки «Найден» и «Нет». Координаты доступны блоку «К найденной точке» и переменным $_return1/$_return2. До поиска выполните «Запомнить экран».",
        "BufferFindImage" => "Ищет шаблон PNG/BMP/JPG в запомненном снимке. Возвращает координаты верхнего левого угла в $_return1/$_return2 и блоку «К найденной точке». Полностью прозрачные пиксели и необязательный цвет фона игнорируются. Допуск задаётся отдельно по R/G/B. Перед поиском нужен блок «Запомнить экран».",
        "BufferScanColor" => "Находит все пиксели цвета в запомненном снимке (до заданного предела). Очищает и заполняет массив парами: [0]=X, [1]=Y, [2]=X, [3]=Y и т. д.; число точек пишет в переменную. Порядок — по строкам сверху вниз и слева направо. Соответствует одноколорному SCANPXL.",
        "BufferScanImage" => "Находит все расположения шаблона в запомненном снимке, включая перекрывающиеся (до заданного предела). Очищает и заполняет массив парами X,Y; число совпадений пишет в переменную. Прозрачность и цвет фона исключают пиксели шаблона. Допуск 0–255 применяется к каждому цветовому каналу.",
        "BufferSave" => "Сохраняет весь текущий запомненный снимок, включая изменения блока «Заменить цвет в снимке», в PNG-файл. Не делает нового захвата экрана. Относительный путь отсчитывается от папки сохранённого проекта.",
        "MoveFound" => "Перемещает курсор к координатам, полученным последним успешным блоком «Найти цвет» или «Найти изображение» в той же ветке, с указанным смещением. Если точка не найдена, сценарий выдаст ошибку. Для клика по центру шаблона задайте половину его ширины/высоты как смещение.",
        "IfWindow" => "Ищет видимое окно по части заголовка без учёта регистра. Выход «Да» при обнаружении, «Нет» иначе. Если подходит несколько окон, берётся первое в порядке Windows.",
        "ActivateWindow" => "Находит видимое окно по части заголовка, восстанавливает и пытается сделать активным. Windows может запретить активацию фоновой программы; для окон администратора Kliker Blocks тоже может потребоваться запуск с правами администратора.",
        "MoveWindow" => "Находит видимое окно по части заголовка и задаёт его положение X/Y и размеры в экранных пикселях. Ширина и высота должны быть положительными. Для окон с повышенными правами могут понадобиться соответствующие права Kliker Blocks.",
        "WindowFind" => "Ищет видимое окно по части заголовка или только по его началу и записывает числовой HWND в переменную; 0 означает отсутствие совпадения. При нескольких совпадениях возвращается первое обнаруженное окно. HWND может устареть после закрытия окна.",
        "WindowInfo" => "Читает экранные X, Y, ширину и высоту окна по числовому HWND в четыре переменные. При несуществующем HWND сообщает об ошибке. Аналог WNDGETINFO.",
        "WindowAction" => "Работает с окном по числовому HWND: позиция (X/Y), размер, геометрия (X/Y/ширина/высота), состояние (0 — свернуть, 1 — восстановить) или активация. Windows может запретить изменение или активацию чужого окна. Аналог WNDPOS, WNDSIZE, WNDSETINFO, WNDSTATE, WNDBUMP.",
        "ElementAtPoint" => "Возвращает числовой HWND элемента под экранной точкой; 0 означает, что элемент не найден. Координаты можно задать выражениями или вставить текущую позицию мыши. Аналог HGET(x,y).",
        "ElementInfo" => "Читает текст стандартного элемента Windows или PID его процесса по HWND в переменную. Для текста используется WM_GETTEXT с таймаутом 500 мс и пределом 4096 символов; нестандартные элементы могут возвращать пустую строку. Аналоги HGETTEXT/HGETPID.",
        "ElementSetText" => "Передаёт WM_SETTEXT элементу по HWND с таймаутом 500 мс и пределом 4096 символов. Windows может запретить запись в другой процесс, а нестандартный элемент может не поддерживать это сообщение. Аналог HSETTEXT.",
        "MessageSend" => "Посылает числовое сообщение (код 0–65535) окну по HWND. «Асинхронно» соответствует POSTMESSAGE: возвращает 1 после постановки в очередь. «Синхронно» соответствует SENDMESSAGE: ждёт ответ не более 500 мс и пишет результат в переменную. wParam/lParam — только целые числа; указатели и строки ими не передаются. Не посылайте неизвестные коды чужим приложениям.",
        "MessageReceive" => "Читает последние wParam/lParam сообщения WM_USER (код 1024), адресованного главному окну этого экземпляра Kliker Blocks. Флаг нового сообщения = 1 один раз после получения; последующие чтения дают 0 до нового сообщения. Перед началом сценария используйте $_hwnd_self для адреса собственного окна. Сообщения другим экземплярам не смешиваются.",
        "RunFile" => "Запускает .exe, .bat, .cmd, ярлык .lnk, документ или другой файл через ассоциации Windows. Нажмите «Выбрать программу или файл…», найдите программу в списке меню «Пуск» или укажите любой существующий файл через Проводник. Путь также можно ввести вручную; относительный путь отсчитывается от папки проекта. Аргументы передаются строкой. Можно ждать завершения и задать таймаут. Если Windows запустила ярлык без дескриптора процесса, ожидание недоступно. Код завершения, когда он есть, записывается в журнал.",
        "RunAhk" => "Запускает .ahk-скрипт именно через AutoHotkey v2. Укажите путь к скрипту и, при необходимости, к AutoHotkey64.exe/AutoHotkey32.exe версии 2. Если поле интерпретатора пусто, выполняется поиск в стандартных папках установки. Аргументы скрипта, ожидание и таймаут настраиваются. Запуск скрипта, созданного для AHK v1, не поддерживается.",
        "RunScenario" => "Запускает сохранённый сценарий .klb последовательно: 1–1000 повторений, скорость 0,1–5,0×, максимум восемь уровней вложенности. Дочерний сценарий делает один проход; явная обратная связь отклоняется. Переменные изолированы. Во «Входах» задайте по строке child_name=значение, например child_name=${user_name}. В «Выходах» задайте parent_name=child_name: после успешного выполнения дочернее значение попадёт в родительскую переменную. Имена только латинские. Остановка основного сценария прерывает дочерний.",
        "Repeat" => "Выполняет ветку «Тело» указанное число раз, затем ОДИН РАЗ переходит в «Далее». «Далее» не является паузой между итерациями. Для задержки внутри каждого повтора разместите «Паузу» в ветке «Тело», например между проверкой и перемещением курсора. Заканчивайте тело блоком «Конец ветки». При числе повторов до 100 журнал показывает каждую итерацию. Число повторов ограничено 100 000.",
        "CallSub" => "Вызывает подпрограмму по имени из блока «Начало подпрограммы». Когда тело доходит до «Возврат из подпрограммы» (или до несоединённого выхода), выполнение продолжается по выходу «Далее» этого блока. Имя ищется без учёта регистра; определения должны быть уникальными. Максимальная глубина вложенных вызовов — 32.",
        "SubStart" => "Начало именованной подпрограммы. Расположите блок отдельно от основной цепочки, задайте уникальное имя и соедините выход «Тело» с первым действием подпрограммы. Завершите тело блоком «Возврат из подпрограммы». Запускайте только через «Вызвать подпрограмму».",
        "SubReturn" => "Аналог END_SUB. Завершает тело вызванной подпрограммы и возвращает выполнение к выходу «Далее» вызывающего блока. Вне подпрограммы этот блок выдаёт ошибку.",
        "Parallel" => "Одновременно запускает ветки A и B и ждёт завершения обеих перед выходом «Далее». Каждая ветка должна завершаться «Концом ветки». Действия ввода выполняются по очереди, чтобы не смешивать одновременные нажатия/клики.",
        "BranchEnd" => "Завершает текущую ветку повтора или параллельного выполнения. В обычной цепочке тоже завершает выполнение.",
        "Log" => "Выводит текст в журнал выполнения. Если ранее выполнен блок «Файл журнала», тот же текст дописывается в указанный файл. Общий файл журнала включается отдельно в меню «Сценарий». Галочка «Записать действия в журнал» добавляет запись и о выполнении самого блока.",
        "LogFile" => "Включает дублирование последующих сообщений PRINT/LOGWRITE и блоков «Сообщение» в UTF-8 файл в папке проекта. Укажите только имя файла без пути, до 160 символов. Файл создаётся при выполнении блока даже без последующих сообщений; полный путь выводится в экранный журнал. Пустое поле выключает запись. Файл дополняется при каждом запуске; размер ограничен 8 МиБ. LOGCLEAR не удаляет и не очищает этот файл.",
        "LogClear" => "Очищает видимые записи встроенного журнала. Если пользовательский интерфейс не подключён, блок проходит дальше без действия. Соответствует LOGCLEAR().",
        "LogShow" => "Показывает или скрывает встроенную панель журнала: 1 — показать, 0 — скрыть. Панель можно открыть вручную через меню «Сценарий». Координаты отдельного окна LOGSHOW пока не поддержаны.",
        "PlaySound" => "Начинает воспроизведение WAV-файла и сразу переходит к следующему блоку. Путь может быть относительным к папке проекта. Если файл не найден или не является WAV, сценарий сообщает ошибку. Соответствует SOUND(file).",
        "SpeakText" => "Озвучивает текст через современные установленные голоса Windows. Поле текста поддерживает ${text} и =выражение, поэтому можно произнести результат предыдущих блоков. Оставьте имя голоса пустым для автоматического выбора по языку текста: для русских букв нужен голос ru (например, Irina или Pavel), для китайских — zh. Кнопка в свойствах показывает голоса Windows и их языки. Явно выбранный голос другого языка вызывает ошибку вместо тихой пустой озвучки. Скорость от -10 до 10, громкость 0–100, длина до 16000 символов. Блок ждёт конца речи; остановка сценария прерывает воспроизведение. Для параллельной работы поместите блок в параллельную ветку. Голоса зависят от Windows; блок не переводит текст.",
        "Beep" => "Воспроизводит системный звуковой сигнал заданной частоты (37–32767 Гц) и длительности (1–5000 мс). Если системный Beep недоступен, используется обычное аудиоустройство Windows. Следующий блок начнётся после сигнала. Если оба способа недоступны, ошибка выводится в журнал. Соответствует BEEP(freq,time).",
        "InputDialog" => "Показывает поле ввода и записывает строку в переменную. Значение по умолчанию возвращается, если время истекло до начала ввода; таймаут 0 означает ждать без ограничения. «Отмена» возвращает пустую строку. Таймаут 0–3600 секунд, по умолчанию 5. Остановка сценария закрывает диалог. Соответствует INPUTBOX(message,default[,delay]). Заголовок, X/Y и размер окна задаются в свойствах этого блока. Оставьте оба X и Y пустыми для размещения по центру экрана; для точной позиции заполните оба поля. Пустые ширина и высота подбираются под текст, но не меньше 435×205; явные значения допустимы: ширина 360–3000, высота 185–3000 пикселей. Координаты относятся к экрану, а не к полю графа.",
        "ChoiceDialog" => "Показывает вопрос. В поле «Кнопки в окне» выбирайте набор по названиям, а не угадывайте номер: 0 — ОК; 1 — ОК/Отмена; 2 — Прервать/Повторить/Игнорировать; 3 — Да/Нет/Отмена; 4 — Да/Нет; 5 — Повторить/Отмена. Номер набора НЕ является кодом ответа. В переменную записывается результат Windows: ОК=1, Отмена=2, Прервать=3, Повторить=4, Игнорировать=5, Да=6, Нет=7. Под выбранным набором в свойствах блока показаны допустимые ответы и их коды. Остановка сценария закрывает диалог. Соответствует DIALOGBOX(message,buttons[,icon]). Заголовок, X/Y и размер окна задаются в свойствах блока. Оставьте оба X/Y пустыми для центра экрана. Пустая ширина или высота автоматически подбирается под вопрос, не меньше 470×190; явные значения: ширина 360–3000, высота 180–3000 пикселей. X/Y — координаты экрана, не графа.",
        "RadioDialog" => @"Показывает варианты по одному на строке (1–100 вариантов, до 250 символов каждый). В свойствах блока нажмите Enter после каждого варианта. В коде графа те же переносы записаны как \n внутри одного value: строка кода остаётся одной строкой, а поле покажет отдельные варианты. Если в свойствах введено \&, в коде это записано как \\&, потому что код также экранирует обратную косую черту. Каждая строка может содержать шаблон, например =[(${counter}+2)*3]& па \&: при counter=1 появится «9 па &». ОК возвращает номер выбранного варианта от 1, отмена или ОК без выбора — 0. Остановка сценария закрывает окно. Заголовок, X/Y и размер окна настраиваются в свойствах блока. Оставьте оба X/Y пустыми для центра экрана. Пустые размеры автоматически подбираются под вопрос и варианты, не меньше 465×410; явные значения: ширина 360–3000, высота 260–3000 пикселей. X/Y относятся к экрану, не к графу.",
        "HintPopup" => "Отправляет необязательное всплывающее уведомление Windows с сообщением и заголовком, затем сразу продолжает сценарий. Для показа используется значок Kliker Blocks в области уведомлений. Системные настройки Windows могут скрыть или задержать показ. Соответствует HINTPOPUP(message[,title]).",
        "Stop" => "Останавливает весь сценарий, в том числе параллельные ветки после их текущего действия. Уже запущенные внешние процессы не закрываются.",
        _ => "Описание пока не добавлено."
    };
}

internal sealed class HelpForm : Form
{
    private const string ShortIntroduction = "Kliker Blocks — визуальный редактор сценариев Windows. Соединяйте блоки, настраивайте условия, циклы, ввод, файлы, снимки и перевод текста. Сценарий можно запускать из редактора, компактной панели или трея. Справка разбита на темы: выберите раздел слева или найдите блок по названию, функции либо параметру. Русская и английская справка встроены; для перевода сценариев нужен подключённый сервис либо отдельно загруженные офлайн-модели.";
    private readonly TreeView _topics = new() { Dock = DockStyle.Fill, HideSelection = false };
    private readonly TextBox _search = new() { Dock = DockStyle.Fill, PlaceholderText = "Поиск: блок, функция, параметр…" };
    private readonly Label _resultCount = new() { Dock = DockStyle.Fill, TextAlign = ContentAlignment.MiddleLeft };
    private readonly RichTextBox _content = new() { Dock = DockStyle.Fill, ReadOnly = true,
        BorderStyle = BorderStyle.None, Font = new Font("Segoe UI", 10.5f),
        BackColor = Color.White, DetectUrls = false };
    private readonly TableLayoutPanel _examplePanel = new() { Dock = DockStyle.Bottom, Height = 278,
        Visible = false, Padding = new Padding(14, 10, 14, 8), BackColor = Color.FromArgb(236, 243, 252),
        RowCount = 4, ColumnCount = 1 };
    private readonly Label _exampleTitle = new() { Dock = DockStyle.Fill,
        Font = new Font("Segoe UI", 11, FontStyle.Bold), ForeColor = Color.FromArgb(30, 76, 132) };
    private readonly Label _exampleNote = new() { Dock = DockStyle.Fill,
        ForeColor = Color.FromArgb(59, 76, 99) };
    private readonly RichTextBox _exampleCodeView = new() { Dock = DockStyle.Fill, ReadOnly = true,
        WordWrap = false, Font = new Font("Consolas", 9.5f), DetectUrls = false,
        BackColor = Color.FromArgb(250, 252, 255), ForeColor = Color.FromArgb(30, 48, 72),
        BorderStyle = BorderStyle.FixedSingle };
    private readonly Button _copyExample = new() { Dock = DockStyle.Right, Width = 224, Visible = false };
    private string? _exampleCode;
    private readonly List<Topic> _allTopics = [];
    private CancellationTokenSource? _translationCancel;
    private int _translationVersion;

    public HelpForm(string? selectedKind)
    {
        Text = UiLanguage.T("Справка Kliker Blocks");
        _search.PlaceholderText = UiLanguage.T("Поиск: блок, функция, параметр…");
        Width = 1050;
        Height = 750;
        StartPosition = FormStartPosition.CenterParent;
        BackColor = Color.FromArgb(247, 249, 253);
        var split = new SplitContainer { Dock = DockStyle.Fill, SplitterDistance = 315,
            FixedPanel = FixedPanel.Panel1, BackColor = Color.FromArgb(222, 231, 243) };
        Controls.Add(split);
        Shown += (_, _) => split.SplitterDistance = 315;
        var navigation = new TableLayoutPanel { Dock = DockStyle.Fill, RowCount = 5, ColumnCount = 1,
            Padding = new Padding(10), BackColor = Color.FromArgb(247, 249, 253) };
        navigation.RowStyles.Add(new RowStyle(SizeType.Absolute, 42));
        navigation.RowStyles.Add(new RowStyle(SizeType.Absolute, 30));
        navigation.RowStyles.Add(new RowStyle(SizeType.Percent, 100));
        navigation.RowStyles.Add(new RowStyle(SizeType.Absolute, 48));
        navigation.RowStyles.Add(new RowStyle(SizeType.Absolute, 48));
        navigation.Controls.Add(_search, 0, 0);
        navigation.Controls.Add(_resultCount, 0, 1);
        navigation.Controls.Add(_topics, 0, 2);
        var website = new Button { Dock = DockStyle.Fill,
            Text = UiLanguage.T("Открыть сайт Kliker Blocks ↗"), Margin = new Padding(0, 8, 0, 0) };
        website.Click += (_, _) => WebsiteLinks.Open(this);
        navigation.Controls.Add(website, 0, 3);
        var support = new Button { Dock = DockStyle.Fill,
            Text = UiLanguage.T("Поддержать проект"), Margin = new Padding(0, 8, 0, 0) };
        support.Click += (_, _) => new SupportForm().Show(this);
        navigation.Controls.Add(support, 0, 4);
        _topics.BorderStyle = BorderStyle.None;
        _topics.BackColor = Color.FromArgb(247, 249, 253);
        _topics.Font = new Font("Segoe UI", 9.5f);
        _topics.ItemHeight = 25;
        _resultCount.ForeColor = Color.FromArgb(82, 99, 121);
        split.Panel1.Controls.Add(navigation);
        var article = new Panel { Dock = DockStyle.Fill, Padding = new Padding(22, 18, 18, 14),
            BackColor = Color.White };
        article.Controls.Add(_content);
        split.Panel2.Controls.Add(article);
        _examplePanel.RowStyles.Add(new RowStyle(SizeType.Absolute, 32));
        _examplePanel.RowStyles.Add(new RowStyle(SizeType.Absolute, 48));
        _examplePanel.RowStyles.Add(new RowStyle(SizeType.Percent, 100));
        _examplePanel.RowStyles.Add(new RowStyle(SizeType.Absolute, 44));
        _examplePanel.Controls.Add(_exampleTitle, 0, 0);
        _examplePanel.Controls.Add(_exampleNote, 0, 1);
        _examplePanel.Controls.Add(_exampleCodeView, 0, 2);
        var exampleBar = new Panel { Dock = DockStyle.Fill, Padding = new Padding(0, 5, 0, 0) };
        _copyExample.Text = UiLanguage.Code == "ru" ? "Копировать граф примера" : "Copy example graph";
        _copyExample.Click += (_, _) =>
        {
            if (_exampleCode is null) return;
            try { Clipboard.SetText(_exampleCode); }
            catch (Exception error)
            {
                MessageBox.Show(this, error.Message, UiLanguage.Code == "ru" ? "Буфер обмена" : "Clipboard",
                    MessageBoxButtons.OK, MessageBoxIcon.Warning);
            }
        };
        exampleBar.Controls.Add(_copyExample);
        _examplePanel.Controls.Add(exampleBar, 0, 3);
        split.Panel2.Controls.Add(_examplePanel);
        AddSection("Общие сведения", "Обзор Kliker Blocks", UiLanguage.Code == "ru"
            ? AppHelp.Introduction : ShowcaseText.Get("help_overview"));
        AddSection("Общие сведения", "Поддержать проект",
            "Поддержка разработки добровольна и не требуется для работы программы. В меню «Поддержать проект» открываются пять предоставленных автором QR-кодов: USDT в сетях TON, TRC20, ERC20, Solana и перевод через Сбербанк. Для USDT выберите ровно ту сеть, которую поддерживает ваш кошелёк. Перед любым переводом проверьте данные получателя, распознанные из QR. Ошибочную транзакцию обычно нельзя отменить. Эти QR-коды также опубликованы на сайте Kliker Blocks.");
        AddSection("Работа со сценарием", "Панель, пауза и трей",
            "Закрытие редактора открывает компактную панель Kliker Blocks. В ней можно запустить, приостановить, продолжить и остановить активный сценарий, а также вернуться в редактор. Закрытие панели прячет её в трей; для полного выхода выберите «Выход из Kliker Blocks» в меню панели или трея. У каждого экземпляра программы свой значок трея и состояние сценария: зелёная точка — выполнение, жёлтая — пауза, серая — готовность. Пауза кооперативная: уже начатое действие и неделимая группа ввода завершаются, затем выполнение ждёт продолжения; остановка работает во время паузы. Удерживаемые Kliker Blocks клавиши и кнопки освобождаются на безопасной границе паузы.");
        AddSection("Работа со сценарием", "Поделиться графом",
            "Нажмите «Поделиться графом…» в редакторе. Проверьте код: свойства блоков могут содержать пути, тексты и другие личные данные. Для небольшого графа откроется заполненное обсуждение GitHub. Для большого графа полный код копируется в буфер — вставьте его в текст обсуждения. Выберите категорию «Графы пользователей» и подтвердите публикацию в браузере. Без подтверждения ничего не публикуется. На сайте граф появится после синхронизации. Перед запуском чужого графа проверьте его работу с файлами, окнами и сетью.");
        AddSection("Работа со сценарием", "Обработка ошибки блока",
            "В свойствах каждого выполняемого блока выберите действие при ошибке: остановить сценарий, пропустить блок и перейти по выходу «Далее» либо перейти к выбранному блоку. Можно настроить 0–10 повторов и задержку 0–60000 мс перед каждым повтором. После обработанной ошибки её текст доступен в переменной ${_last_error} и записывается в журнал. Отмена сценария и возврат из подпрограммы не считаются ошибкой блока. Пример: для блока чтения CSV укажите два повтора с задержкой 500 мс и переход к блоку «Сообщение», который запишет ${_last_error}.");
        AddSection("Работа со сценарием", "Запуск и остановка",
            "Сценарий начинается с единственного блока «Старт». Режимы — один проход или повторять с начала до остановки. Запуск: меню «Сценарий», компактная панель, трей или Ctrl+Alt+F6. Остановка: те же места или Ctrl+Alt+F7. Пауза доступна из меню, панели и трея. Несоединённый выход завершает ветку; обратная связь создаёт цикл.");
        AddSection("Работа со сценарием", "Автозапуск, расписание и обновления",
            "В меню «Сценарий → Автозапуск и расписание сценариев» выберите сохранённый .klb, включите запуск Kliker Blocks при входе в Windows и запуск выбранного сценария. Задержка задаётся от 0 до 3600 секунд. Обычный ручной запуск программы не включает этот сценарий автоматически. Для расписания укажите файл, дату и время до секунды; режимы — один раз или ежедневно. Windows Task Scheduler запускает отдельный экземпляр Kliker Blocks для каждого срабатывания, поэтому разные сценарии могут работать одновременно. Требуется выполненный вход пользователя в Windows; задачи можно включать, выключать и удалять из того же окна. Если компьютер был выключен, планировщик Windows решает, когда выполнить пропущенное задание.\n\n" +
            "В меню «Справка → Проверить обновления» приложение запрашивает публичные выпуски GitHub. При наличии новой версии можно скачать установщик для текущей архитектуры. Программа сверяет размер и SHA-256 с данными GitHub, сохраняет резервную копию открытого графа в AppData\\Local\\KLIKER Blocks\\GraphBackups и запускает установщик. Установщик обновляет файлы программы в выбранной папке; пользовательские .klb, настройки и резервные копии не входят в пакет и не удаляются. Новые графы по умолчанию сохраняются в «Документы\\Kliker Blocks». Меню «Файл → Проверить совместимость графа» проверяет .klb без его изменения. Формат графа v1 остаётся совместимым; если будущий формат потребует преобразования, оно должно сохранять исходный файл и резервную копию.");
        AddSection("Работа со сценарием", "Демонстрация Что я умею",
            "Меню «Что я умею» открывает встроенный граф: Блокнот печатает обращение и пользовательскую русскую фразу. Граф читает весь документ через буфер обмена и сверяет его с ожидаемым, поэтому визуальный перенос строк не создаёт дубликатов. Выберите язык. При наличии локального пакета Argos ru → выбранный язык граф переводит фразу и может озвучить её голосом Windows. Без модели перевод не выполняется: в Блокноте и отчёте появится понятная причина. Затем выберите звезду, сердце или дом. Через восемь секунд без ответа Paint пытается нарисовать мышью стрелку к вопросу; ещё через десять секунд появляется напоминание в другом Блокноте. Ответ отменяет последующие напоминания. Выбранную фигуру Kliker Blocks рисует мышью на пустом белом холсте Paint. Программа ищет карандаш по элементам нового либо классического интерфейса, находит видимые границы холста и проверяет, что рисунок действительно появился. Если инструмент или холст не найден, граф сообщает об ошибке, а не выдаёт пустой холст за успех. Kliker Blocks запоминает область экрана, считает CRC32, сохраняет снимок и текстовый отчёт в папке Showcase; точные пути показывает журнал. Граф можно сохранить в .klb.\n\nПредложение демонстрации сбрасывается при каждой новой версии Kliker Blocks. Действия на рабочем столе начинаются только после подтверждения; повторный просмотр доступен из меню. Остановка/Esc прерывает последующие действия. Созданные файлы и открытые окна остаются, буфер обмена меняется. Голос Windows и модель Argos необязательны, но без модели перевода не будет. Не запускайте демонстрацию поверх чувствительных данных.");
        AddSection("Работа со сценарием", "Окна и точность демонстрации",
            "Блокнот ставится слева, граф Kliker Blocks — справа, если хватает места. Текст печатается с задержкой. Весь документ копируется и сверяется с ожидаемым, а не только видимая строка: автоматический перенос не меняет содержимое. При пропусках Kliker Blocks заменяет весь документ через буфер обмена и проверяет снова. Если текст всё ещё неверен, граф останавливается. Буфер обмена после показа может содержать весь текст Блокнота. Paint открывается с пустым холстом, Kliker Blocks находит карандаш и красный цвет, измеряет видимую белую область и рисует в её пределах мышью. Если интерфейс Paint не распознан или штрихи не появились, граф сообщает об ошибке. Классический Paint недоступен на текущей машине для живого испытания.");
        AddSection("Редактор", "Визуальные блоки и связи",
            "В левой панели заголовки разделов раскрывают списки блоков; первый раздел открыт при запуске. Названия блоков показаны на скруглённых карточках. Панель имеет минимальную ширину, чтобы подписи не обрезались; используйте «Скрыть блоки» в верхней панели редактора, чтобы свернуть её влево, и «Показать блоки», чтобы открыть снова. Поиск раскрывает подходящие блоки. Добавляйте блоки из меню «Блоки» или левой панели. ЛКМ по пустому месту ставит зелёную точку вставки: следующий новый или скопированный блок появится там. Без точки новые блоки размещаются по прежней очереди. Если блок или группа выделены, ЛКМ по пустому месту переносит выделение с центром в точке щелчка и сохраняет расстояния между блоками. ПКМ по пустому месту снимает выделение и убирает точку. Вход и каждый именованный выход находятся на контуре блока; от любого выхода можно провести связь ко входу другого блока. Все точки настраиваются отдельно. Их подписи на блоке скрыты: наведите курсор на точку, чтобы увидеть подсказку; она исчезнет, когда курсор уйдёт. Точка останова показана отдельным квадратным значком паузы и не является разъёмом. Связь со стрелкой прокладывается вокруг других блоков. Щёлкните по связи, чтобы настроить наконечник, сплошную или пунктирную линию, цвет, прозрачность и толщину. У одного выхода одна связь, у входа их может быть много. В свойствах блока откройте «Оформление блока…»: выберите форму (прямоугольник, квадрат, круг, ромб или скруглённый прямоугольник), заливку и окантовку. Для входа и каждого выхода задайте угол точки на контуре: 0° справа, 90° снизу, 180° слева, 270° сверху; также можно щёлкнуть по образцу. Оформление можно применить только к этому блоку или сохранить как стандарт для всех блоков этого типа в настройках программы. При сохранении проекта индивидуальный вид и точки сохраняются вместе с графом. Shift+ЛКМ выделяет область, Ctrl+C/V копирует и вставляет блоки. Delete удаляет блок или связь. Перетаскивание пустого поля сдвигает вид; Ctrl+колесо меняет масштаб. Значок стрелки в панели редактора открывает граф в отдельном окне, а стрелка рядом с заголовком журнала открывает живой журнал отдельно. Свойства выбранного блока находятся справа.");
        AddSection("Редактор", "Выделение тонких связей",
            "Наведите указатель на связь между блоками. Она подсветится синим, а в середине появится круглый маркер. Щёлкните по линии или маркеру, чтобы открыть свойства связи справа. Невидимая область клика шире нарисованной линии и учитывает масштаб и толщину; соседние блоки сохраняют приоритет клика. Выбранную связь можно удалить клавишей Delete.");
        AddSection("Редактор", "Текстовый код Kliker Blocks",
            "Над полем переключатель «Блоки / Код Kliker Blocks». Текст описывает тот же граф без потери циклов и параллельных связей. Форма: block <метка> <тип> <X> <Y> [id <GUID>], затем value \"Поле\" = \"Значение\" и link \"Выход\" -> <метка> либо none, завершение end. Индивидуальный вид блока хранится в строке appearance = {...}, а вид каждого выхода — в style \"Выход\" = {...}; внутри используется JSON. Эти строки обычно удобнее менять через свойства, затем посмотреть код. Глобальный стандарт формы хранится в настройках программы. Значения value записаны как строки JSON: настоящий перенос строки внутри поля показывается в коде как \\n; Windows также использует пару \\r\\n, но код Kliker Blocks при сохранении приводит её к \\n. Обратная косая черта в значении удваивается: шаблонное \\& в свойствах видно как \\\\& в коде. Строка trace true включает запись действий этого блока в журнал, trace false выключает. Новый блок может быть без id; существующие GUID лучше сохранять. Нажмите «Применить код» или вернитесь к блокам. Неверный текст оставляет прежний граф. В справке каждого блока есть отдельный копируемый граф: сохраните свой проект, скопируйте пример, вставьте в режим кода, примените и запустите один проход. Некоторые примеры требуют указанного файла, окна или сервиса.");
        AddSection("Редактор", "Точки и маршруты связей",
            "В «Оформлении блока» для входной и выходных точек отдельно задаются форма (круг, квадрат, ромб, треугольник), размер 6–36, цвет и непрозрачность. Точки остаются на контуре фигуры. Подписи выходов на блоках скрыты; название каждого выхода показывается только в подсказке при наведении. Значок «II» — точка останова: включите её в свойствах блока, чтобы при запуске сценарий остановился перед выполнением этого блока; наведите курсор на значок для подсказки. В оформлении связи размер наконечника задаётся отдельно от толщины линии (4–48). Прямые участки от точки выхода и перед точкой входа задаются отдельно (0–200). Радиус первого изгиба у выхода и последнего изгиба у входа также задаётся отдельно (0–200); ноль оставляет острый угол. Фактический радиус ограничивается длиной соседних участков и уменьшается, если скругление задело бы блок. Между двумя изгибами программа прокладывает соединительный участок. Если оба прямых участка равны нулю и путь свободен, связь может быть прямой; препятствия маршрут обходит. Настройки сохраняются с графом. В текстовом коде breakpoint true ставит точку останова перед блоком.");
        AddSection("Редактор", "Размер и заголовок блока",
            "В свойствах блока откройте «Оформление блока…». Выберите ширину от 196 до 480 единиц, размер заголовка от 7 до 16 пунктов и включите «Автоматически уменьшать заголовок, если он не помещается». При включённой подгонке текст уменьшается только для этого блока до читаемого минимума; ширину можно увеличить вручную. Для блока с точкой останова заголовок располагается правее значка «II». Размер, подгонка и точки сохраняются в проекте вместе с оформлением.");
        AddSection("Редактор", "Отладка сценария",
            "В свойствах блока включите «Точка останова перед блоком». При запуске сценарий остановится перед этим блоком; активный блок подсвечен, а окно отладки показывает текущие переменные. Нажмите «Следующий блок» для одного шага или «Продолжить» для обычного выполнения. Остановить весь сценарий можно стандартной командой «Стоп». Значения переменных могут содержать личные данные: учитывайте это при снимках экрана.");
        AddSection("Переменные", "Переменные и массивы",
            "Имена пользовательских переменных и массивов: только латинские буквы A–Z, a–z, цифры 0–9 и _. Первый знак — буква или _: counter, total_2, _flag. Не подходят 2total, my-value и счётчик. Регистр в именах не различается: Counter и counter — одно имя. Это правило действует на все новые и открытые сценарии; для старых имён переименуйте также все ссылки. Меню «Языки → Проверить имена переменных проекта…» находит неверные имена перед запуском.\n\n" +
            "Создание: «Задать переменную» записывает или заменяет значение; «Объявить переменную» задаёт только если имени ещё нет. «Вычислить переменную» изменяет числовое значение; отсутствующий счётчик начинает с 0. «Если переменная» выбирает Да/Нет. «Удалить переменную» удаляет также одноимённый массив; после UNDEFINE чтение даёт 0. Значение хранится как строка; числовая арифметика требует число.\n\n" +
            "Использование: ${counter} подставляет значение в текстовое/числовое поле перед выполнением блока: «Шаг ${counter}», пауза ${delay_ms}. Если всё поле начинается с =, оно вычисляется как выражение: =($counter+2)*3, =$counter>=10 and $enabled. В выражении пишите $counter, а не ${counter}. Элемент массива: $items[0], размер arrsize($items), извлечение arrpop($items). Блоки «Элемент массива», «Операция с массивом», «Разделить строку», «Список файлов» создают и изменяют массивы; индексы начинаются с 0. Имя массива подчиняется тому же правилу.\n\n" +
            "Все блоки одного запуска видят общие переменные, включая подпрограммы, циклы и параллельные ветки. При повторе до остановки значения сохраняются между проходами; при новом запуске создаётся новое хранилище. Текущие значения в .klb не сохраняются. Параллельные ветки могут менять одно имя в непредсказуемом порядке: используйте разные имена или управляемый порядок связей. Служебные имена $_xmouse, $_ymouse, $_time_h, $_time_m, $_time_s, $_date_y, $_date_m, $_date_d, $_time_str, $_date_str, $_time_t, $_ms, $_xmin, $_ymin, $_xmax, $_ymax читают текущие значения Windows. Не записывайте пароли и токены в переменные, если включаете журнал.");
        AddSection("Переменные", "Смешанный текст и вычисления",
            "Поля блоков вычисляются при выполнении. Для одного результата используйте =($counter+2)*3. Для текста с вычислением начните поле с =[, например: =[(\u0024{counter}+2)*3]& па \\&. Если counter=1, результат будет «9 па &». Внутри [] работает выражение; снаружи одиночный & соединяет части, а \\& выводит обычный знак &. В обычном тексте ${counter} подставляет переменную без вычисления.\n\n" +
            "В выражении доступны +, -, *, /, % (остаток), ** или ^ (степень), скобки, сравнения >, <, >=, <=, ==, !=. Логическое И: && либо and; ИЛИ: || либо or; исключающее ИЛИ: xor; НЕ: ! либо not. Условия возвращают 1 или 0. Внутри [] разрешены $counter и ${counter}; \u0024{counter} снаружи [] — подстановка в текст. Знак & внутри [] больше не означает соединение строк: используйте его только снаружи.\n\n" +
            "В блоке «Выбрать вариант» каждая строка списка вычисляется отдельно. В свойствах нажмите Enter между вариантами: первая строка =[(\u0024{counter}+2)*3]& па \\&, вторая 11, третья 22. В коде графа это одно значение Options с последовательностями \\n перед 11 и 22. Последовательность \\n обозначает настоящий перенос, а не вариант из буквального текста \\n. Если пользователь вводит Windows-перенос \\r\\n, редактор нормализует его до \\n. Для наглядного готового графа откройте справку блока «Выбрать вариант» и скопируйте его пример. Шаблон ограничен 8192 символами; ошибочная формула останавливает сценарий с сообщением, вместо вывода ложного результата.");
        AddSection("Переменные", "Условные выражения и присваивание",
            "В вычисляемом поле пишите =[if (${counter}+2)*3<10 then \"Правда, точно есть\" else_if 35>25 then 22 else 33]. При counter=1 результат — «Правда, точно есть». После if идёт условие, после then — результат. Можно добавить любое число веток else_if условие then результат; else необязателен. Текстовый результат берите в двойные кавычки, число или вычисляемую формулу пишите без кавычек. Пробелы вокруг математических знаков не обязательны. Выполняется только первая подходящая ветка; невыбранные значения не вычисляются. Если ни одна ветка не подошла и else нет, результат FALSE.\n\n" +
            "Краткая форма =[if $counter<10] возвращает TRUE или FALSE. Её можно применять в блоке «Если выражение»: TRUE идёт по выходу «Да», FALSE — по «Нет». Слова if, then, else_if и else пишутся именно так при любом языке интерфейса. Вложенные цепочки if в одном выражении пока не поддерживаются: соедините блоки или вычислите промежуточное значение отдельно.\n\n" +
            "Чтобы одновременно вывести результат и создать либо обновить переменную, добавьте после ] запись => ${xxx}: =[if $counter<10 then \"мало\" else \"много\"] => ${xxx}. Последующие блоки читают ${xxx}. Перед => знак & не нужен; & после ${xxx} соединяет дальнейший текст, например =[if 1 then 9 else 0] => ${xxx}& па \\&. Имя xxx подчиняется правилу A–Z, a–z, 0–9, _; первый символ — буква или _. Если шаблон синтаксически неверен, присваивание не выполняется.");
        AddSection("Журнал", "Журнал и запись в файл",
            "В заголовке журнала есть переключатель «Перенос строк», в том числе в отдельном окне. При включении длинные записи автоматически переносятся по ширине окна; при выключении показываются одной строкой. Выбор сохраняется и влияет только на экран, а не на содержимое файла журнала.\n\nВ свойствах каждого блока есть галочка «Записать действия в журнал». При её включении блок пишет название, короткий идентификатор, фактический выход, разрешённые значения полей и изменения переменных и массивов. Например: параметры Имя=\"counter\", Значение=\"5\"; изменения: counter=\"5\". Ошибка и уже совершённые изменения также записываются. Длинные значения сокращаются до 180 символов, а изменения массива показывают размер и первые три значения; это предотвращает разрастание журнала. Без галочки подробная трассировка блока не добавляется; явные сообщения и диагностика Kliker Blocks остаются. В текстовом коде графа используйте trace true внутри блока. Встроенная демонстрация включает эту галочку для всех своих блоков. Журнал может содержать ввод пользователя и другие конфиденциальные данные; не включайте его для паролей и токенов.\n\n" +
            "Меню «Сценарий → Запись журнала в текстовый файл…» включает полную запись журнала текущего запуска, включая сообщения Kliker Blocks и выбранные действия блоков. Укажите имя .txt/.log без пути: файл создаётся при запуске рядом с сохранённым .klb, а у несохранённого проекта — рядом с Kliker.Blocks.exe. Полный путь виден в настройках и экранном журнале. Запись UTF-8 дополняется при повторном запуске; предел 8 МиБ. Настройка сохраняется в проекте. При недоступном файле запись в него отключается и причина выводится в экранный журнал. Очистка экранного списка файл не очищает. Отдельный блок «Файл журнала» / #logfile создаёт свой файл сразу при выполнении, но записывает только явные сообщения сценария и не заменяет полный журнал. Не включайте файл, если сценарий может выводить секретные данные.");
        AddSection("Захват и макросы", "Снимки и образы",
            "Меню «Захват» сохраняет точку, делает снимок выбранной области и открывает библиотеку. Форма области выбирается при захвате. В блоках поиска изображения выберите сохранённый образ, задайте границы и допуск; полученные координаты можно использовать в следующих блоках.");
        AddSection("Захват и макросы", "Запись макросов",
            "Запись доступна в меню «Макрос». Есть полная запись действий, запись кликов с образами и кликов по доступным элементам Windows. Последний режим создаёт блоки «Дождаться элемента» и «Действие с элементом»; если элемент не удалось распознать, используется координатный клик. Панель записи позволяет поставить запись на паузу, продолжить и остановить. Результат сохраняется в библиотеке и преобразуется в блоки для последующего редактирования. Перед запуском проверьте записанные имена и идентификаторы: приложение может изменить их после обновления.");
        AddSection("Слежение и индикатор", "Слежение за курсором",
            "Блок «Следить за курсором» может активироваться сразу, переключателем или удержанием клавиши; дополнительное условие — ЛКМ, ПКМ, СКМ или другая клавиша. Настраиваются опора, порог смещения, цель возврата, опрос и задержка. Для игры или приложения ввод может зависеть от их режима обработки мыши; обход защиты не поддерживается.");
        AddSection("Слежение и индикатор", "Индикатор сценария",
            "Индикатор показывает запуск и состояние слежения поверх окон. В меню «Сценарий» задаются положение, форма, размер, цвета или изображения для разных состояний, подписи и клавиша показа/скрытия. У каждого экземпляра Kliker Blocks собственный индикатор и собственные настройки проекта.");
        AddSection("Мышь и профили", "Профили и назначения мыши",
            "Откройте «Назначения мыши → Профили, слои и кнопки…». Добавьте профиль и включите общую галочку. Профили проверяются сверху вниз; «Все окна» — запасной вариант. Условия: активное окно или окно под курсором, имя процесса без .exe или с ним, часть заголовка, класс окна/элемента, прямоугольник X/Y/ширина/высота относительно левого верхнего угла окна. Пустое поле процесса, заголовка или класса не ограничивает выбор. У каждого профиля 1–10 слоёв; переключение доступно действием назначения, из меню и трея. В каждом слое создайте строки кнопка/колесо → способ → действие. «Сочетание» срабатывает при нажатии источника, пока другая указанная кнопка удерживается. «Короткое» срабатывает при отпускании, только если не успел сработать долгий порог. «Долгое» запускается после заданного числа миллисекунд; допускается до четырёх порогов для одного источника. «Повтор» запускается сразу и затем с указанным интервалом. «Удержание» и «Переключатель» физически удерживают назначенную клавишу или кнопку; при отключении Kliker Blocks освобождает её. Для действия «Клавиши» пишите сочетание Ctrl+C или последовательность через запятые: Ctrl+C, 100ms, Ctrl+V. Значение действия «Кнопка мыши»: ЛКМ, ПКМ, СКМ, Кнопка 4 или Кнопка 5. Для слоя укажите имя или номер с 1. Галочка «Блокировать исходное» не пропускает исходное событие в окно. Колесо поддерживает только отдельные события прокрутки. Настройки хранятся в проекте и по умолчанию выключены. Ctrl+Alt+F8 переключает назначения; удержание Ctrl+Alt временно пропускает исходную мышь для доступа к управлению. В интерфейсе Kliker Blocks назначения автоматически приостанавливаются. В двух экземплярах сценарии работают одновременно, но переназначение мыши может быть активно только в одном, иначе действия бы дублировались. Системы, не принимающие обычные события Windows, могут игнорировать переназначенный ввод.");
        AddSection("Перевод", "Перевод текста и языковые модели",
            "Меню «Языки → Язык интерфейса и модели перевода…» выбирает RU/EN/FR/ES/ZH, путь Python с argostranslate и необязательный адрес LibreTranslate. Смена языка сразу пересоздаёт интерфейс без закрытия программы пользователем; несохранённый проект сохраняется в памяти. «Перевести текст» поддерживает LibreTranslate /translate (исходный auto допустим) и Argos локально (нужен конкретный исходный язык и установленная пара). «Определить язык» вызывает /detect сервиса, «Если перевод доступен» проверяет /languages; эти два блока требуют работающего сервера. «Перевести массив» работает через выбранный движок. Подставляйте текст через ${source_text}, ответ читайте из указанной переменной. При удалённом сервисе текст передаётся ему. Для машинного перевода подробной справки нужен локальный пакет ru → выбранный язык. Словарь терминов и пользовательские правила пока не реализованы; качество зависит от модели. Документация: https://docs.libretranslate.com/ и https://github.com/argosopentech/argos-translate .");
        AddSection("Перевод", "Установка модели Argos",
            "1. Установите Python с поддержкой argostranslate. В командной строке выполните python -m pip install argostranslate. Если установленный Python 3.14 не работает с зависимостями Argos, попробуйте отдельный Python 3.11 или 3.12.\n\n2. В «Языки → Язык интерфейса и модели перевода…» укажите путь именно к этому python.exe. Нажмите «Проверить Argos». Если видите сообщение об отсутствующем модуле, движок установлен не в выбранный Python.\n\n3. Скачайте с каталога Argos файл .argosmodel нужного направления. Например, ru → en — русский в английский; ar → en — арабский в английский и не заменяет ru → en. Для обратного перевода нужен отдельный пакет.\n\n4. Нажмите «Установить .argosmodel…», выберите скачанный файл. Kliker Blocks проверит содержимое пакета и покажет направление. После установки проверьте его в списке локальных моделей. Затем в блоке «Перевести текст» выберите «Argos локально», источник и цель. Для перевода справки нужен пакет ru → выбранный язык интерфейса.\n\nПроверка LibreTranslate отправляет запрос на указанный адрес, по умолчанию 127.0.0.1:5000. Это отдельный сервер, который Kliker Blocks не запускает. Ошибка соединения означает, что там никто не слушает; для локального Argos это не препятствие. «Определить язык» и «Если перевод доступен» пока требуют сервер LibreTranslate. Модели устанавливайте только из доверенных источников.");
        AddSection("Звук", "Возможности компьютера и голоса",
            "При первом запуске Kliker Blocks сохраняет локальный снимок нужных возможностей в %LOCALAPPDATA%\\KLIKER Blocks\\computer-capabilities.json: версию и архитектуру Windows, .NET, язык интерфейса, раскладки клавиатуры, доступные голоса и размеры экранов. Если эта папка недоступна, файл создаётся рядом с Kliker.Blocks.exe; точный путь показан в окне. Файл не содержит имени пользователя, путей к документам или перечня установленных программ и никуда не отправляется. В меню «Языки → Возможности компьютера и голоса…» можно посмотреть файл и обновить сведения после установки нового голоса или смены экрана. Голоса автоматически не скачиваются и не устанавливаются. Для блока «Озвучить текст» оставьте поле голоса пустым: Kliker Blocks выберет русский либо китайский голос по символам текста, иначе системный голос. Для русской речи нужен голос ru; английский голос Zira не читает русскую фразу корректно. Если голоса нужного языка нет, добавьте его в языковых настройках Windows. Остановка сценария прерывает озвучивание.");
        AddSection("Клавиатура", "Коды клавиш VK (1–255)",
            "Коды Windows VK — десятичное значение, Hex и название. В числовом поле блока вводите десятичное число. В текстовых полях клавиш можно вводить это число или короткое имя. Нажмите кнопку назначения в настройках блока, чтобы заполнить поле без поиска кода. ЛКМ=1, ПКМ=2, СКМ=4. Не все коды назначены Windows; OEM-клавиши зависят от раскладки.\n\n" +
            string.Join("\n", VirtualKeyCatalog.AllCodes().Select(item => $"{item.Code,3}   0x{item.Code:X2}   {item.Name}")));
        foreach (var spec in BlockCatalog.All)
        {
            var english = UiLanguage.Code == "en";
            var title = UiLanguage.T(spec.Title);
            var body = ShowcaseText.HelpBlock(spec.Kind) ?? (english ? EnglishHelp.Block(spec.Kind) ?? AppHelp.For(spec.Kind) :
                UiLanguage.Code == "ru" ? AppHelp.For(spec.Kind) :
                LocalizedHelp.Block(spec.Kind, UiLanguage.Code) ??
                (UiLanguage.Code == "de" ? EnglishHelp.Block(spec.Kind) : null) ?? AppHelp.For(spec.Kind));
            var description = title + "\n\n" + body + "\n\n" + UiLanguage.T("Параметры:") + "\n" +
                (spec.Fields.Length == 0 ? UiLanguage.T("Нет.") : string.Join("\n", spec.Fields.Select(field =>
                    $"• {(english && !UiLanguage.Has(field.Label) ? field.Key : UiLanguage.T(field.Label))} [{field.Key}] ({UiLanguage.T("по умолчанию:")} {UiLanguage.T(field.Default)})"))) +
                "\n\n" + UiLanguage.T("Выходы:") + " " + (spec.Outputs.Length == 0 ? UiLanguage.T("нет") : string.Join(", ", spec.Outputs.Select(UiLanguage.T)));
            _allTopics.Add(new Topic(MainForm.CategoryFor(spec.Kind), spec.Title, spec.Kind, description,
                description + " " + UiLanguage.T(spec.Title) + " " + spec.Kind + " " +
                string.Join(" ", spec.Fields.Select(field => field.Key + " " + UiLanguage.T(field.Label)))));
        }
        _topics.AfterSelect += (_, _) => ShowSelected();
        _search.TextChanged += (_, _) => RefreshTopics(null);
        _search.KeyDown += (_, e) =>
        {
            if (e.KeyCode != Keys.Enter) return;
            e.SuppressKeyPress = true;
            _topics.Focus();
            if (_topics.SelectedNode is null && _topics.Nodes.Count > 0)
                _topics.SelectedNode = _topics.Nodes[0].Nodes.Count > 0 ? _topics.Nodes[0].Nodes[0] : _topics.Nodes[0];
        };
        RefreshTopics(selectedKind);
    }

    private void AddSection(string category, string title, string content)
    {
        var localized = ExpressionHelp.Section(title) ?? JournalHelp.Section(title) ??
            ShowcaseText.HelpSection(title) ?? (UiLanguage.Code == "en" ? EnglishHelp.Section(title) ?? content :
                UiLanguage.Code == "ru" ? content : LocalizedHelp.Section(title, UiLanguage.Code) ??
                (UiLanguage.Code == "de" ? EnglishHelp.Section(title) : null) ?? content);
        _allTopics.Add(new Topic(category, title, null, localized,
            title + " " + UiLanguage.T(title) + " " + localized));
    }

    private void RefreshTopics(string? selectedKind)
    {
        var terms = _search.Text.Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        var matches = _allTopics.Where(topic => MatchesSearch(topic.SearchText, terms)).ToList();
        _topics.BeginUpdate();
        try
        {
            _topics.Nodes.Clear();
            foreach (var group in matches.GroupBy(topic => topic.Category))
            {
                var parent = new TreeNode(UiLanguage.T(group.Key));
                foreach (var topic in group) parent.Nodes.Add(new TreeNode(UiLanguage.T(topic.Title)) { Tag = topic });
                _topics.Nodes.Add(parent);
                if (terms.Length > 0 || selectedKind is not null || group.Key == "Общие сведения") parent.Expand();
            }
            _resultCount.Text = UiLanguage.Format("Найдено тем: {0}", matches.Count);
            var chosen = _topics.Nodes.Cast<TreeNode>().SelectMany(node => node.Nodes.Cast<TreeNode>())
                .FirstOrDefault(node => (node.Tag as Topic)?.Kind == selectedKind) ??
                _topics.Nodes.Cast<TreeNode>().SelectMany(node => node.Nodes.Cast<TreeNode>()).FirstOrDefault();
            if (chosen is not null) _topics.SelectedNode = chosen;
            else
            {
                _examplePanel.Visible = false;
                RenderArticle(UiLanguage.T("Справка Kliker Blocks"),
                    UiLanguage.T("Ничего не найдено. Попробуйте другое слово или название функции."));
            }
        }
        finally { _topics.EndUpdate(); }
    }

    internal static bool MatchesSearch(string searchableText, IEnumerable<string> terms) =>
        terms.All(term => searchableText.Contains(term, StringComparison.CurrentCultureIgnoreCase));

    private async void ShowSelected()
    {
        if (_topics.SelectedNode?.Tag is not Topic topic) return;
        _translationCancel?.Cancel();
        var request = new CancellationTokenSource();
        _translationCancel = request;
        var version = ++_translationVersion;
        try
        {
            _exampleCode = null;
            _copyExample.Visible = false;
            _examplePanel.Visible = false;
            if (UiLanguage.Code is "ru" or "en" or "de" || topic.Title == "Обзор Kliker Blocks")
                RenderArticle(UiLanguage.T(topic.Title), topic.Content);
            else
            {
                RenderArticle(UiLanguage.T(topic.Title), topic.Content);
                try
                {
                    var translated = await HelpTranslationService.TranslateAsync(topic.Content, UiLanguage.Code,
                        AppSettings.Load().ArgosPythonPath, request.Token);
                    if (version != _translationVersion || IsDisposed) return;
                    RenderArticle(UiLanguage.T(topic.Title), translated);
                }
                catch (OperationCanceledException) { return; }
                catch (Exception error)
                {
                    if (version != _translationVersion || IsDisposed) return;
                    // The offline localized summary remains useful when a model is absent.
                    System.Diagnostics.Debug.WriteLine("Detailed help translation unavailable: " + error.Message);
                }
            }
            if (topic.Kind is { } kind)
            {
                var example = BlockExampleCatalog.For(kind);
                _exampleCode = example.Code;
                _copyExample.Visible = true;
                _exampleTitle.Text = UiLanguage.Code == "ru" ? "Пример графа" : "Example graph";
                _exampleNote.Text = (UiLanguage.Code == "ru" ? example.NoteRu : example.NoteEn) +
                    (UiLanguage.Code == "ru"
                        ? " Сохраните свой проект перед применением примера."
                        : " Save your project before applying this example.");
                _exampleCodeView.Text = example.Code;
                _examplePanel.Visible = true;
            }
            var query = _search.Text.Trim();
            if (query.Length > 0)
            {
                var found = _content.Text.IndexOf(query, StringComparison.CurrentCultureIgnoreCase);
                if (found >= 0) { _content.Select(found, query.Length); _content.ScrollToCaret(); }
            }
        }
        finally
        {
            if (ReferenceEquals(_translationCancel, request)) _translationCancel = null;
            request.Dispose();
        }
    }

    private void RenderArticle(string title, string body)
    {
        if (body.StartsWith(title + "\n\n", StringComparison.Ordinal)) body = body[(title.Length + 2)..];
        _content.Text = title + "\n\n" + body;
        _content.SelectAll();
        _content.SelectionColor = Color.FromArgb(43, 54, 70);
        _content.SelectionFont = new Font("Segoe UI", 10.5f);
        _content.SelectionRightIndent = 8;
        _content.Select(0, title.Length);
        _content.SelectionFont = new Font("Segoe UI", 16, FontStyle.Bold);
        _content.SelectionColor = Color.FromArgb(27, 70, 120);
        foreach (System.Text.RegularExpressions.Match match in
                 System.Text.RegularExpressions.Regex.Matches(_content.Text,
                     @"(?m)^(Параметры:|Выходы:|Parameters:|Outputs:|\d+\.)"))
        {
            _content.Select(match.Index, match.Length);
            _content.SelectionFont = new Font("Segoe UI", 10.5f, FontStyle.Bold);
            _content.SelectionColor = Color.FromArgb(34, 90, 149);
        }
        _content.Select(0, 0);
        _content.ScrollToCaret();
    }

    protected override void OnFormClosed(FormClosedEventArgs e)
    {
        _translationCancel?.Cancel();
        base.OnFormClosed(e);
    }

    private sealed record Topic(string Category, string Title, string? Kind, string Content, string SearchText);
}
